import{_ as i,o as t,c as h,ae as g}from"./chunks/framework.BONZgKEB.js";const s=JSON.parse('{"title":"Quy trình Ghi điểm & Trận đấu","description":"","frontmatter":{},"headers":[],"relativePath":"vi/guide/scoring-workflow.md","filePath":"vi/guide/scoring-workflow.md"}'),o={name:"vi/guide/scoring-workflow.md"};function a(c,n,r,e,l,u){return t(),h("div",null,[...n[0]||(n[0]=[g('<h1 id="quy-trinh-ghi-điem-tran-đau" tabindex="-1">Quy trình Ghi điểm &amp; Trận đấu <a class="header-anchor" href="#quy-trinh-ghi-điem-tran-đau" aria-label="Permalink to &quot;Quy trình Ghi điểm &amp; Trận đấu&quot;">​</a></h1><p>Hướng dẫn này trình bày cách các vận động viên và trọng tài nhập và theo dõi điểm số trong cả Vòng Phân hạng và Vòng Loại bằng cách sử dụng bảng điểm kỹ thuật số.</p><h2 id="_1-truy-cap-bang-điem" tabindex="-1">1. Truy cập Bảng điểm <a class="header-anchor" href="#_1-truy-cap-bang-điem" aria-label="Permalink to &quot;1. Truy cập Bảng điểm&quot;">​</a></h2><p>Trong một cuộc thi đang diễn ra, người dùng được ủy quyền (Vận động viên và Trọng tài) có thể truy cập bảng điểm trực tiếp từ thiết bị của họ.</p><ol><li>Điều hướng đến <strong>Cuộc thi</strong> đang diễn ra.</li><li>Tùy thuộc vào giai đoạn hiện tại, hãy chọn <strong>Phân hạng</strong> hoặc <strong>Loại trực tiếp</strong>.</li><li>Tìm Bia hoặc Trận đấu được phân công của bạn và nhấp vào <strong>Nhập Điểm</strong>.</li></ol><blockquote><p><strong>Lưu ý:</strong> Chỉ vận động viên được phân công hoặc trọng tài chính thức của sự kiện mới có thể nhập điểm cho một bia cụ thể.</p></blockquote><h2 id="_2-ghi-điem-vong-phan-hang" tabindex="-1">2. Ghi điểm Vòng Phân hạng <a class="header-anchor" href="#_2-ghi-điem-vong-phan-hang" aria-label="Permalink to &quot;2. Ghi điểm Vòng Phân hạng&quot;">​</a></h2><p>Chế độ xem Phân hạng cung cấp một bản sao kỹ thuật số của phiếu ghi điểm bắn cung truyền thống.</p><h3 id="nhap-điem-theo-luot-ban-ends" tabindex="-1">Nhập Điểm theo Lượt bắn (Ends) <a class="header-anchor" href="#nhap-điem-theo-luot-ban-ends" aria-label="Permalink to &quot;Nhập Điểm theo Lượt bắn (Ends)&quot;">​</a></h3><ol><li>Phiếu ghi điểm được chia thành các <strong>Lượt bắn (Ends)</strong> (thường là 3 hoặc 6 mũi tên mỗi lượt).</li><li>Nhập giá trị của mỗi mũi tên được bắn theo thứ tự giảm dần (ví dụ: 10, 9, 9, 8, 8, 7).</li><li>Hệ thống sẽ tự động tính toán: <ul><li><strong>Tổng điểm Lượt:</strong> Tổng điểm các mũi tên trong lượt hiện tại.</li><li><strong>Tổng điểm Tích lũy:</strong> Điểm tích lũy cho toàn bộ vòng đấu.</li><li><strong>10 và X:</strong> Hệ thống tự động đếm số điểm 10 và các điểm 10 ở vòng trong (X) phục vụ cho mục đích giải quyết hòa (tie-breaking).</li></ul></li></ol><h3 id="bang-xep-hang-truc-tiep" tabindex="-1">Bảng xếp hạng Trực tiếp <a class="header-anchor" href="#bang-xep-hang-truc-tiep" aria-label="Permalink to &quot;Bảng xếp hạng Trực tiếp&quot;">​</a></h3><p>Khi điểm số được gửi theo từng lượt, <strong>Bảng xếp hạng Trực tiếp</strong> sẽ tự động cập nhật. Điều này cho phép khán giả, huấn luyện viên và vận động viên xem bảng xếp hạng theo thời gian thực mà không cần đợi đến cuối giải đấu.</p><h2 id="_3-ghi-điem-vong-loai-cac-tran-đau" tabindex="-1">3. Ghi điểm Vòng Loại (Các Trận đấu) <a class="header-anchor" href="#_3-ghi-điem-vong-loai-cac-tran-đau" aria-label="Permalink to &quot;3. Ghi điểm Vòng Loại (Các Trận đấu)&quot;">​</a></h2><p>Việc ghi điểm trong một trận đấu loại khác nhau tùy thuộc vào loại cung (Cung 1 dây so với Cung trợ lực). Ứng dụng tự động điều chỉnh giao diện ghi điểm dựa trên luật thi đấu.</p><h3 id="cung-1-day-recurve-he-thong-điem-set-set-system" tabindex="-1">Cung 1 dây (Recurve): Hệ thống Điểm Set (Set System) <a class="header-anchor" href="#cung-1-day-recurve-he-thong-điem-set-set-system" aria-label="Permalink to &quot;Cung 1 dây (Recurve): Hệ thống Điểm Set (Set System)&quot;">​</a></h3><p>Các trận đấu Cung 1 dây sử dụng Hệ thống Điểm Set.</p><ol><li>Vận động viên bắn các lượt (set) gồm 3 mũi tên.</li><li>Nhập giá trị mũi tên cho cả hai vận động viên.</li><li>Hệ thống tính tổng điểm của lượt (set total). <ul><li>Vận động viên có tổng điểm lượt cao hơn nhận được <strong>2 Điểm Set</strong>.</li><li>Nếu hòa, cả hai nhận được <strong>1 Điểm Set</strong>.</li></ul></li><li>Vận động viên đầu tiên đạt được <strong>6 Điểm Set</strong> sẽ thắng trận đấu.</li></ol><h3 id="cung-tro-luc-compound-ghi-điem-tich-luy" tabindex="-1">Cung trợ lực (Compound): Ghi điểm Tích lũy <a class="header-anchor" href="#cung-tro-luc-compound-ghi-điem-tich-luy" aria-label="Permalink to &quot;Cung trợ lực (Compound): Ghi điểm Tích lũy&quot;">​</a></h3><p>Các trận đấu Cung trợ lực sử dụng ghi điểm tích lũy.</p><ol><li>Vận động viên bắn các lượt gồm 3 mũi tên.</li><li>Nhập giá trị mũi tên cho cả hai vận động viên.</li><li>Hệ thống duy trì tổng điểm tích lũy.</li><li>Sau số lượt được chỉ định (thường là 5 lượt, tổng cộng 15 mũi tên), vận động viên có tổng điểm cao nhất sẽ thắng trận đấu.</li></ol><h3 id="giai-quyet-hoa-shoot-offs" tabindex="-1">Giải quyết Hòa (Shoot-offs) <a class="header-anchor" href="#giai-quyet-hoa-shoot-offs" aria-label="Permalink to &quot;Giải quyết Hòa (Shoot-offs)&quot;">​</a></h3><p>Nếu một trận đấu có kết quả hòa vào cuối thời gian thi đấu chính thức (ví dụ: 5-5 Điểm Set, hoặc 145-145 Điểm Tích lũy), hệ thống sẽ yêu cầu thực hiện <strong>Shoot-off (Bắn mũi tên quyết định)</strong>.</p><ol><li>Mỗi vận động viên bắn một mũi tên duy nhất.</li><li>Nhập điểm số.</li><li>Nếu điểm số giống hệt nhau (ví dụ: cả hai đều bắn trúng điểm 10), trọng tài phải đo khoảng cách đến tâm. Bạn có thể đánh dấu mũi tên nào gần tâm hơn trên hệ thống để xác định người chiến thắng.</li></ol>',23)])])}const p=i(o,[["render",a]]);export{s as __pageData,p as default};
